import { expect, expectTypeOf, assertType } from "./test/expect-shim.mjs";
import { dedent } from "./src/string/dedent.js";
{
{
{
const upper = (strings, ...values) => {
            let result = '';
            for (let i = 0; i < strings.length; i++) {
                result += strings[i];
                if (i < values.length) {
                    result += String(values[i]);
                }
            }
            return result.toUpperCase();
        };
        const dedentedUpper = dedent(upper);
        const result = dedentedUpper `
      hello
      world
    `;
        expect(result).toBe('HELLO\nWORLD');
}
}
}

